<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','Management');$pageTitle='Booking Change Requests';$rows=db()->query('SELECT cr.*,b.booking_ref,u.full_name,e.title event_title FROM booking_change_requests cr JOIN bookings b ON b.id=cr.booking_id JOIN users u ON u.id=cr.requested_by JOIN events e ON e.id=b.event_id ORDER BY cr.created_at DESC')->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Post-confirmation workflow</div><h1 class="admin-title">Change requests</h1><p class="kicker">Confirmed bookings are locked. Users request changes here for management review.</p></div></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Booking</th><th>Owner</th><th>Event</th><th>Requested</th><th>Proposed time</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['booking_ref'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['event_title'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?= $r['proposed_start_at'] ? date('d M Y · H:i',strtotime($r['proposed_start_at'])) : '—' ?></td><td><span class="badge <?=$r['status']==='approved'?'badge-green':($r['status']==='rejected'?'badge-red':'badge-gold')?>"><?=e($r['status'])?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No change requests.</td></tr><?php endif;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
